41132e2c:  ;
 ;Scheduling a new PTF assignment;
 ;
 ;Variables:
 ;   CA = Effective date/time of current assignment
 ;   DGPMA = Prev. assignment; DGPMP = Curr. assignment
 ;   DGPMT = Action: (1=add, 2=edit, 3=late edit)
 ;   DGJTCA = IEN of previous active assignment
 ;   DGJTDA = IEN of new assignment
 ;   DGONE = Flag to indicate incomplete records need updating;
 ;           (DGQUIET is external variable)
 ;   DGPMDA = IEN of Patient Movement event

5437dc15: ;
 ;This block processes existing Incomplete Records entries for the current
 ;admission and updates or creates new entries as needed based on the
 ;values in DGPMA and DGPMP.
 ;

